import {applicationRoutes} from '../../src/application/routes.js';
import {digest,base64url} from '../../src/security/crypto.js';
const AT='2026-10-01T16:00:00Z';
export async function ownerHTTP(f){const now=Date.now(),token='A'.repeat(43);f.insert('security_owner',{id:1,password_salt:'fixture',password_hash:'fixture',password_iterations:600000,password_revision:1,last_password_change:AT,created_at:now,updated_at:now});f.insert('security_sessions',{token_hash:await digest(token),password_revision:1,created_at:now,expires_at:now+86400000});f.insert('security_installation',{id:1,vault_key_id:'fixture',vault_key:base64url(new Uint8Array(32).fill(9)),created_at:now});return (path,body,method=body?'PUT':'GET')=>applicationRoutes(new Request('https://myts.test'+path,{method,headers:{cookie:'myts_session='+token,origin:'https://myts.test','content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{})}),{}, {db:f.db,installation:{inspect:async()=>({state:'ready'})},syncOptions:{wake:async()=>{}}});}
